+++ b/training/level-1/L1-008-csv-clean/csvClean.mjs
@@ -0,0 +1,90 @@
+export function csvClean(input) {
+  if (input === '') return '';
+  
+  const lines = input.split('\n');
+  let result = '';
+  let inQuote = false;
+  let currentField = '';
+  let currentLine = '';
+  let currentRecord = [];
+  
+  for (let i = 0; i < lines.length; i++) {
+    const line = lines[i];
+    let j = 0;
+    
+    while (j < line.length) {
+      if (line[j] === '"') {
+        inQuote = !inQuote;
+        j++;
+        continue;
+      }
+      
+      if (inQuote) {
+        if (line[j] === '"') {
+          currentField += '"';
+          j++;
+        } else if (line[j] === '\r') {
+          // Skip CR if inside quote
+          j++;
+        } else {
+          currentField += line[j];
+          j++;
+        }
+      } else {
+        if (line[j] === ',') {
+          currentRecord.push(currentField);
+          currentField = '';
+          j++;
+        } else if (line[j] === '\r') {
+          // Skip CR if not in quote
+          j++;
+        } else {
+          currentField += line[j];
+          j++;
+        }
+      }
+    }
+    
+    if (!inQuote) {
+      if (currentField !== '') {
+        currentRecord.push(currentField);
+        currentField = '';
+      }
+      
+      if (currentRecord.length > 0) {
+        const fieldHasSpecial = currentRecord.some(field => 
+          field.includes(',') || field.includes('"') || 
+          field.includes('\r') || field.includes('\n')
+        );
+        
+        if (fieldHasSpecial) {
+          result += '"';
+        }
+        
+        for (let k = 0; k < currentRecord.length; k++) {
+          if (k > 0) result += ',';
+          result += currentRecord[k];
+          
+          if (fieldHasSpecial && currentRecord[k].includes('"')) {
+            result += '"';
+          }
+        }
+        
+        if (fieldHasSpecial) {
+          result += '"';
+        }
+        
+        result += '\n';
+      }
+      
+      currentRecord = [];
+    }
+  }
+  
+  // Remove terminal empty record
+  if (result.endsWith('\n')) {
+    result = result.slice(0, -1);
+  }
+  
+  return result;
+}

